"""Generated by vibe-rescue: Kafka infrastructure validation tests.

These tests connect to the REAL Kafka broker and validate that all topics
referenced in consumer/producer config exist. Run with --pro-mode flag.

Catches: topic not created, topic name typo, broker unreachable,
consumer group issues, missing produced topics.
"""
import pytest
import re
from pathlib import Path


SERVICE_ROOT = Path(__file__).parent.parent

# ADAPT: List all topics consumed by your service
CONSUMED_TOPICS = [
    # "my-service-events-v1",
    # "my-service-orders-v1",
]

# ADAPT: List produced topic base constants (topics constructed dynamically)
PRODUCED_TOPIC_BASES = [
    # "my-service-output-base",
]

# ADAPT: Set the expected total consumed topic count for sanity check
EXPECTED_CONSUMED_TOPIC_COUNT = 0  # ADAPT: your count

# ADAPT: Regex pattern for your topic naming convention
TOPIC_NAMING_PATTERN = re.compile(
    r"^[a-z][a-z0-9-]*$"  # ADAPT: your topic naming regex, or auto-set from memory.yaml
)

# ADAPT: Path to your consumer config file (for config alignment tests)
CONSUMER_CONFIG_PATH = SERVICE_ROOT / "consumers" / "consumer_config.py"  # ADAPT


def _get_broker_topics(kafka_admin):
    """List all topics in the Kafka broker."""
    return set(kafka_admin.list_topics())


def _ensure_topics_exist(kafka_admin, topics):
    """Create topics if they don't exist (for auto.create.topics.enable=false)."""
    try:
        from kafka.admin import NewTopic
        existing = _get_broker_topics(kafka_admin)
        missing = [t for t in topics if t not in existing]
        if missing:
            new_topics = [
                NewTopic(name=t, num_partitions=1, replication_factor=1)
                for t in missing
            ]
            kafka_admin.create_topics(new_topics=new_topics, validate_only=False)
        return missing
    except Exception:
        return []


# =============================================================================
# Broker Connectivity
# =============================================================================

@pytest.mark.infra
@pytest.mark.infra_kafka
class TestInfraKafkaBrokerConnectivity:
    """Validate Kafka broker is reachable and functional."""

    def test_infra_kafka_broker_is_reachable(self, kafka_admin):
        topics = _get_broker_topics(kafka_admin)
        assert isinstance(topics, set), "Failed to list topics from broker"

    def test_infra_kafka_broker_cluster_info(self, kafka_admin):
        metadata = kafka_admin.describe_cluster()
        assert metadata is not None, "Could not retrieve cluster metadata"


