# =============================================================================
# Consumer Config Alignment
# =============================================================================

@pytest.mark.infra
@pytest.mark.infra_kafka
class TestInfraKafkaConsumerConfigAlignment:
    """Validate consumer config file topics match what's in the broker."""

    def test_infra_kafka_all_config_topics_exist_in_broker(self, kafka_admin):
        """Every active topic in the consumer config must exist in broker."""
        if not CONSUMER_CONFIG_PATH.exists():
            pytest.skip(f"Consumer config file not found: {CONSUMER_CONFIG_PATH}")

        content = CONSUMER_CONFIG_PATH.read_text()
        active_topics = set()
        for line in content.split("\n"):
            stripped = line.strip()
            if stripped.startswith("#"):
                continue
            matches = re.findall(r'"([a-z][-a-z0-9_.]+)"', stripped)  # ADAPT: adjust regex to match your topic string pattern
            active_topics.update(matches)

        _ensure_topics_exist(kafka_admin, list(active_topics))
        broker_topics = _get_broker_topics(kafka_admin)
        missing = active_topics - broker_topics
        assert not missing, (
            f"Topics in consumer config not found in broker: {sorted(missing)}"
        )

    def test_infra_kafka_consumed_topic_count_matches(self, kafka_admin):
        """Sanity check: number of consumed topics matches expected count."""
        if EXPECTED_CONSUMED_TOPIC_COUNT == 0:
            pytest.skip("EXPECTED_CONSUMED_TOPIC_COUNT not configured (set to 0)")

        if not CONSUMER_CONFIG_PATH.exists():
            pytest.skip(f"Consumer config file not found: {CONSUMER_CONFIG_PATH}")

        content = CONSUMER_CONFIG_PATH.read_text()
        active_topics = set()
        for line in content.split("\n"):
            stripped = line.strip()
            if stripped.startswith("#"):
                continue
            matches = re.findall(r'"([a-z][-a-z0-9_.]+)"', stripped)  # ADAPT: adjust regex to match your topic string pattern
            active_topics.update(matches)

        assert len(active_topics) == EXPECTED_CONSUMED_TOPIC_COUNT, (
            f"Expected {EXPECTED_CONSUMED_TOPIC_COUNT} consumed topics, "
            f"found {len(active_topics)}: {sorted(active_topics)}"
        )
